const std=@import("std");
export fn hill_encoder(v:[*]const i64,n:usize,out:[*]u8,cap:usize)i64{if(n<10 or n>74)return -1;const lenv=v[0];if(lenv<0 or lenv>64 or n!=10+@as(usize,@intCast(lenv)))return -1;const len:usize=@intCast(lenv);const padded=(len+2)/3*3;var text:[66]i64=@splat(0);var key:[9]i64=undefined;var res:[66]i64=@splat(0);for(0..len)|i|{if(v[1+i]<65 or v[1+i]>90)return -1;text[i]=v[1+i];}for(len..padded)|i|{text[i]=32;}for(0..9)|i|{key[i]=v[1+len+i];if(key[i]<-2 or key[i]>2)return -1;}var off:usize=0;while(off<padded):(off+=3){for(0..3)|row|{var sum:i64=0;for(0..3)|col|{sum+=key[row*3+col]*text[off+col];}if(sum<0 or sum>65535)return -1;res[off+row]=sum;}}const bytes=padded*8;if(cap<bytes)return -2;for(0..padded)|i|{const b=@as(u64,@bitCast(res[i]));for(0..8)|k|{out[i*8+k]=@truncate(b>>(8*k));}}return @intCast(bytes);}
